ALTER TABLE "orders" DROP CONSTRAINT "orders_stripe_ids_match_collection", ADD CONSTRAINT "orders_stripe_ids_match_collection" CHECK (("collection" = 'stripe_invoice' and "stripe_account_id" is not null and "stripe_customer_id" is not null and "stripe_invoice_id" is not null) or ("collection" <> 'stripe_invoice' and "stripe_payment_intent_id" is null and (("stripe_account_id" is null and "stripe_customer_id" is null and "stripe_invoice_id" is null) or ("stripe_account_id" is not null and "stripe_customer_id" is not null and "stripe_invoice_id" is not null))));